class BookingPeriod {
    private int startDay; // 1 to 31
    private int endDay;   // 1 to 31

    public BookingPeriod(int start, int end) {
        if (start >= 1 && start <= 31 && end >= start && end <= 31) {
            this.startDay = start;
            this.endDay = end;
        } else {
            // Safe fallback
            this.startDay = 1;
            this.endDay = 1;
        }
    }

    public void updatePeriod(int newStart, int newEnd) {
        if (newStart < 1 || newEnd > 31 || newStart > newEnd) {
            System.out.println("Invalid period: start cannot be after end.");
            return;
        }
        this.startDay = newStart;
        this.endDay = newEnd;
        System.out.println("Period updated: Day " + startDay + " to " + endDay);
    }

    public int getDurationDays() {
        return (endDay - startDay) + 1;
    }
}

public class Main {
    public static void main(String[] args) {
        BookingPeriod booking = new BookingPeriod(5, 12);
        System.out.println("Initial duration: " + booking.getDurationDays() + " days");

        booking.updatePeriod(20, 10); // End before start -> Rejected!
        booking.updatePeriod(15, 22); // Valid!
        System.out.println("New duration: " + booking.getDurationDays() + " days");
    }
}

