class MatchScore {
    private int teamAScore;
    private int teamBScore;

    public MatchScore() {
        this.teamAScore = 0;
        this.teamBScore = 0;
    }

    public void updateScore(int newA, int newB) {
        if (newA >= teamAScore && newB >= teamBScore) {
            this.teamAScore = newA;
            this.teamBScore = newB;
        } else {
            System.out.println("Invalid score revision");
        }
    }

    public String getScoreString() {
        return teamAScore + " - " + teamBScore;
    }
}

public class Main {
    public static void main(String[] args) {
        MatchScore match = new MatchScore();
        match.updateScore(1, 0);
        match.updateScore(0, 2);
        match.updateScore(2, 1);
        System.out.println("Score: " + match.getScoreString());
    }
}
